107	// TestPollWakesOnCommit exercises a real listener: one client parks with a
108	// long wait, another request commits the first new change, and the parked
109	// client receives the page promptly with timedOut=false.
110	func TestPollWakesOnCommit(t *testing.T) {
111		h, _ := newTestHandler(t)
112		srv := httptest.NewServer(h)
113		defer srv.Close()
114	
115		// Seed one change so the document is known and the poll parks after it.
116		seedDoc(t, h, "doc", 1)
117	
118		type resp struct {
119			status int
120			body   map[string]any
121			err    error
122		}
123		got := make(chan resp, 1)
124		go func() {
125			r, err := http.Get(srv.URL + "/v1/documents/doc/changes/poll?after=1&waitMs=10000")
126			if err != nil {
127				got <- resp{err: err}
128				return
129			}
130			defer r.Body.Close()
131			raw, _ := io.ReadAll(r.Body)
132			var body map[string]any
133			_ = json.Unmarshal(raw, &body)
134			got <- resp{status: r.StatusCode, body: body}
135		}()
136	
137		// Wait until the poll is parked, then commit from a second client.
138		time.Sleep(100 * time.Millisecond)
139		postJSON(t, h, "/v1/documents/doc/changes", map[string]any{
140			"deviceId": "dev",
141			"changes":  []any{map[string]any{"id": "c2", "payload": map[string]any{"n": 2}}},
142		})
143	
144		select {
145		case r := <-got:
146			if r.err != nil {
147				t.Fatalf("poll request: %v", r.err)
148			}
149			if r.status != 200 {
150				t.Fatalf("status = %d body = %v", r.status, r.body)
151			}
152			rows := r.body["changes"].([]any)
153			if len(rows) != 1 || rows[0].(map[string]any)["id"] != "c2" {
154				t.Fatalf("woken rows = %v", rows)
155			}
156			if r.body["nextCursor"].(float64) != 2 || r.body["timedOut"] != false {
157				t.Fatalf("woken page = %v", r.body)
158			}
159		case <-time.After(3 * time.Second):
160			t.Fatal("parked poll was not woken by the commit")
161		}
162	}
